package com.match.transfer;import com.match.entity.User;import com.match.security.*;import com.match.util.result.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/training-transfers")public class TemporaryTransferController{private final RoleGuard roles;private final TemporaryTransferService service;public TemporaryTransferController(RoleGuard r,TemporaryTransferService s){roles=r;service=s;}@PostMapping public ResponseResult<Object> upload(@RequestParam String environmentId,@RequestPart MultipartFile file){User u=roles.requireBusinessUser();return Response.makeOKRsp(service.upload(u.getUserId(),roles.roleOf(u)==UserRole.ADMIN,environmentId,file));}@GetMapping public ResponseResult<Object> list(){User u=roles.requireBusinessUser();return Response.makeOKRsp(service.list(u.getUserId()));}}
